mapper.select:
SELECT f.*, CASE WHEN REGEXP_LIKE( f.ORIGINAL_NAME, '^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}(\.[^.]*)?$' ) THEN NVL(( SELECT MAX(NULLIF(TRIM(i.TITLE), '')) KEEP (DENSE_RANK LAST ORDER BY i.RECORD_ITEM_ID) FROM CONTENT_RECORD_ITEMS i WHERE i.RECORD_TYPE = 'FILE' AND i.CONTENT_ID = f.CONTENT_FILE_ID AND NVL(i.DELETED_YN, 'N') = 'N' ), f.ORIGINAL_NAME) ELSE f.ORIGINAL_NAME END AS DISPLAY_NAME, CASE WHEN f.SCOPE_TYPE IN ('GROUP', 'PROJECT') AND NVL(wmp.USE_ACCOUNT_PROFILE, 'Y') = 'N' THEN NVL(wmp.DISPLAY_NAME, u.USER_NAME) ELSE u.USER_NAME END AS CREATOR_NAME, CASE WHEN f.SCOPE_TYPE IN ('GROUP', 'PROJECT') AND NVL(wmp.USE_ACCOUNT_PROFILE, 'Y') = 'N' THEN wmp.PROFILE_IMAGE_PATH WHEN NVL(u.PROFILE_AVATAR_TYPE, 'DEFAULT') = 'IMAGE' THEN u.PROFILE_IMAGE_PATH ELSE NULL END AS CREATOR_PROFILE_IMAGE_PATH, CASE WHEN f.SCOPE_TYPE IN ('GROUP', 'PROJECT') AND NVL(wmp.USE_ACCOUNT_PROFILE, 'Y') = 'N' THEN CASE WHEN wmp.PROFILE_IMAGE_PATH IS NOT NULL THEN 'IMAGE' ELSE 'DEFAULT' END ELSE NVL(u.PROFILE_AVATAR_TYPE, 'DEFAULT') END AS CREATOR_PROFILE_AVATAR_TYPE, CASE WHEN EXISTS ( SELECT 1 FROM CONTENT_SHARES s WHERE s.CONTENT_TYPE = 'FILE' AND s.CONTENT_ID = f.CONTENT_FILE_ID AND s.ACTIVE_YN = 'Y' AND NVL(s.SHARE_STATUS, 'ACCEPTED') = 'ACCEPTED' AND (s.EXPIRES_AT IS NULL OR s.EXPIRES_AT >= SYSDATE) ) THEN 'Y' ELSE 'N' END AS SHARED_YN FROM CONTENT_FILES f LEFT JOIN USERS u ON u.USER_ID = f.CREATED_BY LEFT JOIN PROJECTS p ON p.PROJ_ID = f.PROJ_ID LEFT JOIN WS_MEMBER_PROFILES wmp ON wmp.WS_ID = CASE WHEN f.SCOPE_TYPE = 'GROUP' THEN f.WS_ID WHEN f.SCOPE_TYPE = 'PROJECT' THEN p.WS_ID ELSE NULL END AND wmp.USER_ID = f.CREATED_BY WHERE f.DELETED_YN = 'N' AND f.SCOPE_TYPE = #{scopeType}
AND f.OWNER_USER_ID = #{ownerUserId}
AND f.WS_ID = #{wsId}
AND f.PROJ_ID = #{projId}
AND f.FOLDER_ID IS NULL
AND f.FOLDER_ID = #{folderId}
AND ( UPPER(f.ORIGINAL_NAME) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(u.USER_NAME) LIKE '%' || UPPER(#{keyword}) || '%' )
ORDER BY
f.CREATED_AT DESC f.FILE_SIZE DESC LOWER(f.ORIGINAL_NAME), f.CONTENT_FILE_ID

SELECT * FROM ( SELECT f.*, f.ORIGINAL_NAME AS DISPLAY_NAME, u.USER_NAME AS CREATOR_NAME, CASE WHEN NVL(u.PROFILE_AVATAR_TYPE, 'DEFAULT') = 'IMAGE' THEN u.PROFILE_IMAGE_PATH END AS CREATOR_PROFILE_IMAGE_PATH, NVL(u.PROFILE_AVATAR_TYPE, 'DEFAULT') AS CREATOR_PROFILE_AVATAR_TYPE, CAST(NULL AS DATE) AS LAST_ACCESSED_AT, CASE WHEN EXISTS ( SELECT 1 FROM CONTENT_SHARES cs WHERE cs.CONTENT_TYPE = 'FILE' AND cs.CONTENT_ID = f.CONTENT_FILE_ID AND cs.ACTIVE_YN = 'Y' AND NVL(cs.SHARE_STATUS, 'ACCEPTED') = 'ACCEPTED' AND (cs.EXPIRES_AT IS NULL OR cs.EXPIRES_AT >= SYSDATE) ) THEN 'Y' ELSE 'N' END AS SHARED_YN FROM CONTENT_FILES f LEFT JOIN USERS u ON u.USER_ID = f.CREATED_BY WHERE f.DELETED_YN = 'N' AND f.SCOPE_TYPE = #{scopeType}
AND f.OWNER_USER_ID = #{ownerUserId} AND f.WS_ID = #{wsId} AND f.PROJ_ID = #{projId}
ORDER BY f.CREATED_AT DESC, f.CONTENT_FILE_ID DESC ) WHERE ROWNUM <= 30
